function dateLabel(value?: string | null) { return value ? new Date(value).toLocaleDateString('en-GB', { day: '2-digit', month: 'short', year: 'numeric' }) : '—'; }
function pct(value?: number | null) { return `${Math.round(value ?? 0)}%`; }
function tone(status?: string) {
  if (!status) return 'neutral';
  if (['Completed', 'Covered', 'Active', 'Open', 'Attended'].includes(status)) return 'teal';
  if (['In Progress', 'Pending', 'Planned'].includes(status)) return 'amber';
  if (['Cancelled', 'Archived', 'Inactive', 'Transferred', 'Absent'].includes(status)) return 'rose';
  return 'neutral';
}
function canDeleteRecord(record: any) { const user=getCurrentUser(); if(!user) return false; if(user.isAdmin) return true; if(record?.createdByUserId != null) return Number(record.createdByUserId)===user.id; const ownerName=record?.createdByName ?? record?.addedBy ?? null; return Boolean(ownerName && ownerName===user.name); }
function canEditSession(record: any) { const user=getCurrentUser(); if(!user) return false; if(user.isAdmin) return true; const trainerId=record?.trainer?.id ?? record?.trainerId; return Number(trainerId)===user.id; }
function canGraduateBatch(batch: any) { const user=getCurrentUser(); if(!user) return false; if(user.isAdmin) return true; return Number(batch?.trainerId)===user.id; }
function canManageBatch(batch:any){ const user=getCurrentUser(); if(!user)return false; return Boolean(user.isAdmin||Number(batch?.trainer?.id??batch?.trainerId)===user.id); }

function Badge({ children }: { children?: React.ReactNode }) {
  return <span className={`inline-flex items-center rounded-full px-2.5 py-1 text-[11px] font-bold badge-${tone(String(children))}`}>{children}</span>;
}
function Button({ children, onClick, type = 'button', variant = 'primary', disabled = false, testId }: { children: React.ReactNode; onClick?: () => void; type?: 'button' | 'submit'; variant?: 'primary' | 'quiet' | 'outline'; disabled?: boolean; testId: string }) {
  const cls = variant === 'primary' ? 'bg-[hsl(var(--primary))] text-[hsl(var(--primary-foreground))] hover:opacity-90' : variant === 'outline' ? 'border border-[hsl(var(--border))] bg-[hsl(var(--card))] hover:bg-[hsl(var(--accent))]' : 'bg-[hsl(var(--muted))] hover:bg-[hsl(var(--accent))]';
  return <button type={type} onClick={onClick} disabled={disabled} data-testid={testId} className={`inline-flex items-center justify-center gap-2 rounded-xl px-3.5 py-2.5 text-sm font-bold disabled:cursor-not-allowed disabled:opacity-50 ${cls}`}>{children}</button>;
}
function PageHeader({ eyebrow, title, description, action }: { eyebrow: string; title: string; description?: string; action?: React.ReactNode }) {
  return <div className="mb-7 flex flex-col justify-between gap-4 sm:flex-row sm:items-end"><div><p className="eyebrow">{eyebrow}</p><h1 className="display-font mt-1 text-3xl font-semibold tracking-tight md:text-[2.65rem]">{title}</h1>{description && <p className="mt-2 max-w-2xl text-sm text-[hsl(var(--muted-foreground))]">{description}</p>}</div>{action}</div>;
}
function EmptyState({ icon: Icon = Sparkles, title, description, action }: { icon?: typeof Sparkles; title: string; description: string; action?: React.ReactNode }) {
  return <div className="empty-grid flex min-h-[225px] flex-col items-center justify-center rounded-2xl border border-dashed border-[hsl(var(--border))] px-6 text-center"><span className="mb-4 grid size-11 place-items-center rounded-2xl bg-[hsl(var(--accent))] text-[hsl(var(--primary))]"><Icon size={21} /></span><h3 className="font-semibold">{title}</h3><p className="mt-1 max-w-sm text-sm text-[hsl(var(--muted-foreground))]">{description}</p>{action && <div className="mt-5">{action}</div>}</div>;
}
function SkeletonRows({ count = 3 }: { count?: number }) { return <div className="space-y-3">{Array.from({ length: count }).map((_, i) => <div key={i} className="skeleton h-14 rounded-xl" />)}</div>; }
function Modal({ title, onClose, children }: { title: string; onClose: () => void; children: React.ReactNode }) {
  useEffect(() => {
    const onKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };
    const previousOverflow = document.body.style.overflow;
    const previousPaddingRight = document.body.style.paddingRight;
    const scrollbarWidth = window.innerWidth - document.documentElement.clientWidth;
    document.body.style.overflow = 'hidden';
    if (scrollbarWidth > 0) document.body.style.paddingRight = `${scrollbarWidth}px`;
    document.addEventListener('keydown', onKeyDown);
    return () => {
      document.body.style.overflow = previousOverflow;
      document.body.style.paddingRight = previousPaddingRight;
      document.removeEventListener('keydown', onKeyDown);
    };
  }, [onClose]);

  if (typeof document === 'undefined') return null;
  return createPortal(<div className="fixed inset-0 z-[1000] grid place-items-center overflow-y-auto bg-[hsl(222_44%_17%/.35)] p-3 backdrop-blur-sm sm:p-5" role="presentation" onMouseDown={(event) => { if (event.target === event.currentTarget) onClose(); }}>
    <div className="my-auto flex max-h-[calc(100dvh-1.5rem)] w-full max-w-3xl flex-col overflow-hidden rounded-3xl bg-[hsl(var(--card))] shadow-2xl sm:max-h-[calc(100dvh-2.5rem)]" role="dialog" aria-modal="true" aria-label={title} onMouseDown={(event) => event.stopPropagation()}>
      <div className="flex shrink-0 items-center justify-between border-b border-[hsl(var(--border))] bg-[hsl(var(--card)/.98)] px-6 py-4 backdrop-blur">
        <h2 className="display-font text-2xl font-semibold">{title}</h2>
        <button type="button" onClick={onClose} className="grid size-9 place-items-center rounded-xl border border-[hsl(var(--border))] text-[hsl(var(--muted-foreground))] hover:bg-[hsl(var(--muted))] hover:text-[hsl(var(--foreground))]" aria-label={`Close ${title}`} data-testid="button-close-modal"><X size={18} /></button>
      </div>
      <div className="min-h-0 overflow-y-auto p-6">{children}</div>
    </div>
  </div>, document.body);
}

